<?php
require __DIR__.'/../includes/bootstrap.php';require_permission('staff');$msg='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$action=$_POST['action']??'';if($action==='save'){ $id=(int)($_POST['id']??0);$name=trim($_POST['full_name']??'');$email=strtolower(trim($_POST['email']??''));$role=$_POST['role']??'';$pass=(string)($_POST['password']??'');$valid=['assistant','orders','products'];if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||!in_array($role,$valid,true))$error='تحقق من الاسم والبريد والصلاحية.';elseif(!$id&&strlen($pass)<12)$error='كلمة المرور يجب ألا تقل عن 12 حرفاً.';else{if($id){if($pass!==''){if(strlen($pass)<12)$error='كلمة المرور يجب ألا تقل عن 12 حرفاً.';else db()->prepare('UPDATE admins SET full_name=?,email=?,username=?,role=?,password_hash=? WHERE id=? AND role<>\'owner\'')->execute([$name,$email,$email,$role,password_hash($pass,PASSWORD_DEFAULT),$id]);}else db()->prepare('UPDATE admins SET full_name=?,email=?,username=?,role=? WHERE id=? AND role<>\'owner\'')->execute([$name,$email,$email,$role,$id]);}else db()->prepare('INSERT INTO admins(full_name,email,username,password_hash,role,is_active) VALUES(?,?,?,?,?,1)')->execute([$name,$email,$email,password_hash($pass,PASSWORD_DEFAULT),$role]);$msg='تم حفظ الحساب.';}}
if($action==='toggle'){ $id=(int)$_POST['id'];if($id!==(int)$_SESSION['admin_id'])db()->prepare("UPDATE admins SET is_active=IF(is_active=1,0,1) WHERE id=? AND role<>'owner'")->execute([$id]);$msg='تم تحديث حالة الحساب.';}}
$edit=null;if(isset($_GET['edit'])){$q=db()->prepare("SELECT id,full_name,email,role FROM admins WHERE id=? AND role<>'owner'");$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}
$users=db()->query('SELECT id,full_name,email,role,is_active,created_at FROM admins ORDER BY id')->fetchAll();
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>الموظفون والمديرون</title><link rel="stylesheet" href="../assets/css/store.css"></head><body><main class="inner"><a href="index.php">← لوحة التحكم</a><h1>المديرون والموظفون</h1><?php if($msg):?><p class="notice"><?=h($msg)?></p><?php endif?><?php if($error):?><p class="notice"><?=h($error)?></p><?php endif?><form method="post" class="admin-form"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=h($edit['id']??'')?>"><label>الاسم<input name="full_name" required value="<?=h($edit['full_name']??'')?>"></label><label>البريد الإلكتروني<input name="email" type="email" required value="<?=h($edit['email']??'')?>"></label><label>الصلاحية<select name="role"><option value="assistant" <?=($edit['role']??'')==='assistant'?'selected':''?>>مدير مساعد</option><option value="orders" <?=($edit['role']??'')==='orders'?'selected':''?>>موظف الطلبات</option><option value="products" <?=($edit['role']??'')==='products'?'selected':''?>>موظف المنتجات والأقسام</option></select></label><label>كلمة المرور <?= $edit?'(اتركها فارغة دون تغيير)':'(12 حرفاً على الأقل)' ?><input type="password" name="password" <?= $edit?'':'required minlength="12"' ?>></label><button class="gold">حفظ الحساب</button></form><div class="table-wrap"><table><tr><th>الاسم</th><th>البريد</th><th>الصلاحية</th><th>الحالة</th><th>الإجراءات</th></tr><?php foreach($users as $u):?><tr><td><?=h($u['full_name'])?></td><td><?=h($u['email'])?></td><td><?=h($u['role'])?></td><td><?=$u['is_active']?'نشط':'معطل'?></td><td><?php if($u['role']!=='owner'):?><a href="?edit=<?=$u['id']?>">تعديل</a><form method="post" class="inline"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$u['id']?>"><button><?=$u['is_active']?'تعطيل':'تفعيل'?></button></form><?php else:?>المدير الرئيسي<?php endif?></td></tr><?php endforeach?></table></div></main></body></html>